A.aSq=new B.am("filament","CALIBRA\xc7\xc3O","Primeira camada est\xe1vel","Ajuste mesa, bico e offset Z antes de imprimir.",A.aIs,"Se o bico tocar a mesa, suba o offset Z aos poucos.",null)
